import { useEffect, useRef, useState } from 'react'
import DOMPurify from 'dompurify'
import './App.css'

type Availability = 'available' | 'downloadable' | 'downloading' | 'unavailable'
type PortfolioTab = { id: string; label: string; prompt: string }
type ModelMonitor = { addEventListener: (type: 'downloadprogress', listener: (event: { loaded: number }) => void) => void }
type PromptSession = {
  prompt: (input: string | Array<{ role: string; content: string }>, options?: { signal?: AbortSignal; responseConstraint?: object }) => Promise<string>
  promptStreaming: (input: string, options?: { signal?: AbortSignal }) => ReadableStream<string>
  destroy: () => void
}
type LanguageModelApi = {
  availability: (options: object) => Promise<Availability>
  create: (options?: { initialPrompts?: Array<{ role: string; content: string }>; monitor?: (monitor: ModelMonitor) => void }) => Promise<PromptSession>
}

declare global { interface Window { LanguageModel?: LanguageModelApi } }

const modelOptions = { expectedInputs: [{ type: 'text', languages: ['en'] }], expectedOutputs: [{ type: 'text', languages: ['en'] }] }
const tabSchema = { type: 'object', properties: { tabs: { type: 'array', minItems: 3, maxItems: 3, items: { type: 'object', properties: { id: { type: 'string' }, label: { type: 'string' }, prompt: { type: 'string' } }, required: ['id', 'label', 'prompt'] } } }, required: ['tabs'] }
const fallbackTabs: PortfolioTab[] = [
  { id: 'systems', label: 'Systems at scale', prompt: 'Focus on professional engineering experience and impact.' },
  { id: 'experiments', label: 'Side experiments', prompt: 'Focus on personal projects, product work, and technical curiosity.' },
  { id: 'outside', label: 'Outside the stack', prompt: 'Focus on education, leadership, interests, and the ideas behind the work.' },
]
const fallbackCanvas = `<article class="canvas-intro"><p class="eyebrow">A portfolio, re-composed</p><h1>Engineering systems<br /><em>with a point of view.</em></h1><p class="lead">Luke Cheng works where distributed systems, scientific thinking, and human-scale tools overlap.</p></article><div class="canvas-grid"><section class="feature-block"><p class="eyebrow">Now / New York</p><h2>Customer data, made legible.</h2><p>At JPMorgan Chase, Luke contributes to a CQRS-style platform serving more than 10M daily requests. Kafka, Cassandra, CockroachDB, and Kubernetes become less interesting as technologies and more interesting as a living system.</p></section><aside class="margin-note"><span>01</span><p>Read this portfolio as a set of connections, not a chronological list.</p></aside></div><section class="signal-row"><div><strong>10M+</strong><span>daily requests</span></div><div><strong>150+</strong><span>hours saved annually</span></div><div><strong>3</strong><span>domains crossed</span></div></section>`
const systemPrompt = `You are the local portfolio editor for Luke Cheng. The complete source of truth is the portfolio markdown supplied below. Never invent facts, companies, dates, metrics, technologies, links, or responsibilities. You may make the presentation surprising and editorial, but every factual claim must be traceable to the source.

For canvas requests, return only semantic HTML and inline style attributes for layout. Never return markdown, code fences, script, style, iframe, form controls, SVG, images, event handlers, or javascript URLs. Use only article, aside, div, section, header, h1, h2, h3, p, ul, ol, li, a, strong, em, small, time, dl, dt, and dd. Make the composition feel like a thoughtful personal website, not a generic resume.

Portfolio source:
`

function sanitizeCanvas(html: string) {
  const withoutFences = html.replace(/^\s*```(?:html)?\s*/i, '').replace(/\s*```\s*$/i, '')
  return DOMPurify.sanitize(withoutFences, { ALLOWED_TAGS: ['article', 'aside', 'div', 'section', 'header', 'h1', 'h2', 'h3', 'p', 'ul', 'ol', 'li', 'a', 'strong', 'em', 'small', 'time', 'dl', 'dt', 'dd', 'br'], ALLOWED_ATTR: ['class', 'href', 'target', 'rel', 'style'], FORBID_ATTR: ['onclick', 'onload', 'onerror'] })
}

function App() {
  const [portfolio, setPortfolio] = useState('')
  const [tabs, setTabs] = useState(fallbackTabs)
  const [activeTab, setActiveTab] = useState(fallbackTabs[0].id)
  const [canvas, setCanvas] = useState(fallbackCanvas)
  const [question, setQuestion] = useState('')
  const [availability, setAvailability] = useState<Availability | 'checking'>('checking')
  const [isReady, setIsReady] = useState(false)
  const [isGenerating, setIsGenerating] = useState(false)
  const [progress, setProgress] = useState(0)
  const [error, setError] = useState('')
  const sessionRef = useRef<PromptSession | null>(null)
  const abortRef = useRef<AbortController | null>(null)

  useEffect(() => {
    let cancelled = false
    const boot = async () => {
      try {
        const [source, status] = await Promise.all([fetch('/portfolio.md').then((response) => response.text()), window.LanguageModel?.availability(modelOptions) ?? Promise.resolve('unavailable' as const)])
        if (cancelled) return
        setPortfolio(source); setAvailability(status)
        if (status === 'available') await createSession(source)
      } catch { if (!cancelled) setError('The portfolio source could not be loaded.') }
    }
    void boot()
    return () => { cancelled = true; abortRef.current?.abort(); sessionRef.current?.destroy() }
  }, [])

  const createSession = async (source: string) => {
    if (!window.LanguageModel) return
    try {
      const session = await window.LanguageModel.create({ initialPrompts: [{ role: 'system', content: `${systemPrompt}\n${source}` }], monitor: (monitor) => monitor.addEventListener('downloadprogress', (event) => setProgress(event.loaded)) })
      sessionRef.current = session; setIsReady(true); setAvailability('available')
      const result = await session.prompt('Create exactly three concise navigation tabs for this portfolio. Return JSON matching the requested schema.', { responseConstraint: tabSchema })
      const parsed = JSON.parse(result) as { tabs?: PortfolioTab[] }
      if (parsed.tabs?.length === 3) setTabs(parsed.tabs)
    } catch { setError('Local AI could not start. The preview remains available.') }
  }

  const activateModel = () => { if (portfolio) { setError(''); setAvailability('downloading'); void createSession(portfolio) } }
  const generateCanvas = async (tab: PortfolioTab, requestedQuestion = '') => {
    const session = sessionRef.current
    if (!session) return
    abortRef.current?.abort()
    const controller = new AbortController(); abortRef.current = controller
    setIsGenerating(true); setError('')
    let output = ''
    try {
      const request = `Compose the main portfolio canvas for the view “${tab.label}”. ${tab.prompt} ${requestedQuestion ? `Answer this visitor question while composing: ${requestedQuestion}` : ''} Use a clear hierarchy, one unusual but usable layout, and only facts from the source. Return semantic HTML only.`
      for await (const chunk of session.promptStreaming(request, { signal: controller.signal })) { output += chunk; setCanvas(sanitizeCanvas(output)) }
    } catch (generationError) { if ((generationError as Error).name !== 'AbortError') setError('This composition could not be generated. Your previous view is still here.') }
    finally { setIsGenerating(false) }
  }
  const handleTabChange = (tab: PortfolioTab) => { setActiveTab(tab.id); void generateCanvas(tab) }
  const handleQuestion = (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const trimmedQuestion = question.trim(); if (!trimmedQuestion) return; setQuestion(''); const tab = tabs.find((item) => item.id === activeTab) ?? tabs[0]; void generateCanvas(tab, trimmedQuestion) }
  const statusLabel = availability === 'checking' ? 'Checking local model' : availability === 'available' && isReady ? 'Local AI ready' : availability === 'downloading' ? 'Downloading local model' : availability === 'unavailable' ? 'Chrome AI unavailable' : 'Local model available'

  return (
    <div className="site-shell">
      <header className="site-header"><div className="identity"><span className="identity-mark">LC / 26</span><div><strong>Luke Cheng</strong><span>Software engineer · systems thinker</span></div></div><div className="model-status"><span className={`status-dot ${isReady ? 'ready' : ''}`} />{statusLabel}</div><form className="question-bar" onSubmit={handleQuestion}><span className="prompt-symbol">↳</span><input value={question} onChange={(event) => setQuestion(event.target.value)} placeholder="Ask the portfolio a question..." aria-label="Ask the portfolio a question" disabled={!isReady || isGenerating} /><button type="submit" aria-label="Ask question" disabled={!isReady || !question.trim() || isGenerating}>Ask</button></form><nav className="tab-nav" aria-label="Portfolio views">{tabs.map((tab, index) => <button key={tab.id} className={activeTab === tab.id ? 'active' : ''} type="button" onClick={() => handleTabChange(tab)} disabled={!isReady || isGenerating}><span>0{index + 1}</span>{tab.label}</button>)}</nav></header>
      <main className="canvas-wrap">
        {availability !== 'available' && !isReady && <section className="ai-gate" aria-live="polite"><span className="eyebrow">Local inference layer</span><h2>{availability === 'unavailable' ? 'This portfolio needs Chrome’s built-in AI.' : availability === 'downloading' ? 'The model is arriving locally.' : 'A browser-native portfolio, still warming up.'}</h2><p>{availability === 'unavailable' ? 'Open this site in a supported desktop version of Chrome with Prompt API access. The editorial preview remains available below.' : 'The first visit downloads the model to your device. Nothing in this portfolio is sent to a remote AI service.'}</p>{availability === 'downloading' && <div className="progress-track"><span style={{ width: `${Math.max(progress * 100, 4)}%` }} /></div>}{availability !== 'unavailable' && availability !== 'downloading' && <button className="primary-button" type="button" onClick={activateModel}>Enable local AI <span>↗</span></button>}{error && <p className="error-message">{error}</p>}</section>}
        <section className={`generated-canvas ${isGenerating ? 'is-generating' : ''}`} aria-live="polite" dangerouslySetInnerHTML={{ __html: sanitizeCanvas(canvas) }} />
        {isGenerating && <div className="generation-note"><span className="pulse" /> Composing a new view <button type="button" onClick={() => abortRef.current?.abort()}>Stop</button></div>}{error && isReady && <div className="inline-error">{error} <button type="button" onClick={() => setError('')}>Dismiss</button></div>}
      </main>
      <footer className="site-footer"><p><span className="footer-signal" /> Content and layout are generated locally by your browser’s AI. Changing views may generate new content.</p><div className="footer-links"><a href="https://github.com/Luke-Cheng" target="_blank" rel="noreferrer">GitHub ↗</a><a href="https://www.linkedin.com/in/luke-cheng/" target="_blank" rel="noreferrer">LinkedIn ↗</a><a href="/portfolio.md">View source ↗</a></div></footer>
    </div>
  )
}

export default App

