import { useEffect, useRef, useState } from "react";
import DOMPurify from "dompurify";
import "./App.css";

type Availability =
  | "available"
  | "downloadable"
  | "downloading"
  | "unavailable";
type PortfolioTab = { id: string; label: string; prompt: string };
type ModelMonitor = {
  addEventListener: (
    type: "downloadprogress",
    listener: (event: { loaded: number }) => void,
  ) => void;
};
type PromptSession = {
  prompt: (
    input: string | Array<{ role: string; content: string }>,
    options?: { signal?: AbortSignal; responseConstraint?: object },
  ) => Promise<string>;
  promptStreaming: (
    input: string,
    options?: { signal?: AbortSignal },
  ) => ReadableStream<string>;
  destroy: () => void;
};
type LanguageModelApi = {
  availability: (options: object) => Promise<Availability>;
  create: (options?: {
    initialPrompts?: Array<{ role: string; content: string }>;
    monitor?: (monitor: ModelMonitor) => void;
  }) => Promise<PromptSession>;
};

declare global {
  interface Window {
    LanguageModel?: LanguageModelApi;
  }
}

const modelOptions = {
  expectedInputs: [{ type: "text", languages: ["en"] }],
  expectedOutputs: [{ type: "text", languages: ["en"] }],
};
const tabSchema = {
  type: "object",
  properties: {
    tabs: {
      type: "array",
      minItems: 3,
      maxItems: 3,
      items: {
        type: "object",
        properties: {
          id: { type: "string" },
          label: { type: "string" },
          prompt: { type: "string" },
        },
        required: ["id", "label", "prompt"],
      },
    },
  },
  required: ["tabs"],
};
const fallbackTabs: PortfolioTab[] = [
  {
    id: "systems",
    label: "Systems at scale",
    prompt: "Focus on professional engineering experience and impact.",
  },
  {
    id: "experiments",
    label: "Side experiments",
    prompt:
      "Focus on personal projects, product work, and technical curiosity.",
  },
  {
    id: "outside",
    label: "Outside the stack",
    prompt:
      "Focus on education, leadership, interests, and the ideas behind the work.",
  },
];
const fallbackCanvas = `<article class="canvas-intro"><p class="eyebrow">A portfolio, re-composed</p><h1>Engineering systems<br /><em>with a point of view.</em></h1><p class="lead">Luke Cheng works where distributed systems, scientific thinking, and human-scale tools overlap.</p></article><div class="canvas-grid"><section class="feature-block"><p class="eyebrow">Now / New York</p><h2>Customer data, made legible.</h2><p>At JPMorgan Chase, Luke contributes to a CQRS-style platform serving more than 10M daily requests. Kafka, Cassandra, CockroachDB, and Kubernetes become less interesting as technologies and more interesting as a living system.</p></section><aside class="margin-note"><span>01</span><p>Read this portfolio as a set of connections, not a chronological list.</p></aside></div><section class="signal-row"><div><strong>10M+</strong><span>daily requests</span></div><div><strong>150+</strong><span>hours saved annually</span></div><div><strong>3</strong><span>domains crossed</span></div></section>`;
const systemPrompt = `You are the local portfolio editor for Luke Cheng. The complete source of truth is the portfolio markdown supplied below. Never invent facts, companies, dates, metrics, technologies, links, or responsibilities. You may make the presentation surprising and editorial, but every factual claim must be traceable to the source.

For canvas requests, return only semantic HTML and inline style attributes for layout. Never return markdown, code fences, script, style, iframe, form controls, SVG, images, event handlers, or javascript URLs. Use only article, aside, div, section, header, h1, h2, h3, p, ul, ol, li, a, strong, em, small, time, dl, dt, and dd. Make the composition feel like a thoughtful personal website, not a generic resume.

Portfolio source:
`;

function sanitizeCanvas(html: string) {
  const withoutFences = html
    .replace(/^\s*```(?:html)?\s*/i, "")
    .replace(/\s*```\s*$/i, "");
  return DOMPurify.sanitize(withoutFences, {
    ALLOWED_TAGS: [
      "article",
      "aside",
      "div",
      "section",
      "header",
      "h1",
      "h2",
      "h3",
      "p",
      "ul",
      "ol",
      "li",
      "a",
      "strong",
      "em",
      "small",
      "time",
      "dl",
      "dt",
      "dd",
      "br",
    ],
    ALLOWED_ATTR: ["class", "href", "target", "rel", "style"],
    FORBID_ATTR: ["onclick", "onload", "onerror"],
  });
}

function App() {
  const [portfolio, setPortfolio] = useState("");
  const [tabs, setTabs] = useState(fallbackTabs);
  const [activeTab, setActiveTab] = useState(fallbackTabs[0].id);
  const [canvas, setCanvas] = useState(fallbackCanvas);
  const [question, setQuestion] = useState("");
  const [availability, setAvailability] = useState<Availability | "checking">(
    "checking",
  );
  const [isReady, setIsReady] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [hasEntered, setHasEntered] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState("");
  const sessionRef = useRef<PromptSession | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  const createSession = async (source: string) => {
    if (!window.LanguageModel) return;
    try {
      const session = await window.LanguageModel.create({
        initialPrompts: [
          { role: "system", content: `${systemPrompt}\n${source}` },
        ],
        monitor: (monitor) =>
          monitor.addEventListener("downloadprogress", (event) =>
            setProgress(event.loaded),
          ),
      });
      sessionRef.current = session;
      setIsReady(true);
      setAvailability("available");
      const result = await session.prompt(
        "Create exactly three concise navigation tabs for this portfolio. Return JSON matching the requested schema.",
        { responseConstraint: tabSchema },
      );
      const parsed = JSON.parse(result) as { tabs?: PortfolioTab[] };
      if (parsed.tabs?.length === 3) setTabs(parsed.tabs);
    } catch {
      setError("Local AI could not start. The preview remains available.");
    }
  };

  useEffect(() => {
    let cancelled = false;
    const boot = async () => {
      try {
        const [source, status] = await Promise.all([
          fetch("/portfolio.md").then((response) => response.text()),
          window.LanguageModel?.availability(modelOptions) ??
            Promise.resolve("unavailable" as const),
        ]);
        if (cancelled) return;
        setPortfolio(source);
        setAvailability(status);
        if (status === "available") await createSession(source);
      } catch {
        if (!cancelled) setError("The portfolio source could not be loaded.");
      }
    };
    void boot();
    return () => {
      cancelled = true;
      abortRef.current?.abort();
      sessionRef.current?.destroy();
    };
  }, []);

  const activateModel = () => {
    if (portfolio) {
      setError("");
      setAvailability("downloading");
      void createSession(portfolio);
    }
  };
  const generateCanvas = async (tab: PortfolioTab, requestedQuestion = "") => {
    const session = sessionRef.current;
    if (!session) return;
    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;
    setIsGenerating(true);
    setError("");
    let output = "";
    try {
      const request = `Compose the main portfolio canvas for the view “${tab.label}”. ${tab.prompt} ${requestedQuestion ? `Answer this visitor question while composing: ${requestedQuestion}` : ""} Use a clear hierarchy, one unusual but usable layout, and only facts from the source. Return semantic HTML only.`;
      for await (const chunk of session.promptStreaming(request, {
        signal: controller.signal,
      })) {
        output += chunk;
        setCanvas(sanitizeCanvas(output));
      }
    } catch (generationError) {
      if ((generationError as Error).name !== "AbortError")
        setError(
          "This composition could not be generated. Your previous view is still here.",
        );
    } finally {
      setIsGenerating(false);
    }
  };
  const handleTabChange = (tab: PortfolioTab) => {
    setActiveTab(tab.id);
    void generateCanvas(tab);
  };
  const handleQuestion = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const trimmedQuestion = question.trim();
    if (!trimmedQuestion) return;
    setQuestion("");
    const tab = tabs.find((item) => item.id === activeTab) ?? tabs[0];
    void generateCanvas(tab, trimmedQuestion);
  };
  const enterPortfolio = () => setHasEntered(true);
  const statusLabel =
    availability === "checking"
      ? "Checking local model"
      : availability === "available" && isReady
        ? "Local AI ready"
        : availability === "downloading"
          ? "Downloading local model"
          : availability === "unavailable"
            ? "Chrome AI unavailable"
            : "Local model available";

  return (
    <div className="site-shell">
      <header className={`site-header ${hasEntered ? "is-entered" : "is-landing"}`}>
        <button className="identity" type="button" onClick={enterPortfolio} aria-label="Enter Luke Cheng's portfolio">
          <span className="identity-mark">LC / 26</span>
          <div>
            <strong>Luke Cheng</strong>
            <span>Software engineer · systems thinker</span>
          </div>
          {!hasEntered && <span className="identity-action">Enter portfolio <b>↗</b></span>}
        </button>
        {hasEntered && <div className="model-status">
          <span className={`status-dot ${isReady ? "ready" : ""}`} />
          {statusLabel}
        </div>}
        {hasEntered && <form className="question-bar" onSubmit={handleQuestion}>
          <span className="prompt-symbol">↳</span>
          <input
            value={question}
            onChange={(event) => setQuestion(event.target.value)}
            placeholder="Ask the portfolio a question..."
            aria-label="Ask the portfolio a question"
            disabled={!isReady || isGenerating}
          />
          <button
            type="submit"
            aria-label="Ask question"
            disabled={!isReady || !question.trim() || isGenerating}
          >
            Ask
          </button>
        </form>}
        {hasEntered && <nav className="tab-nav" aria-label="Portfolio views">
          {tabs.map((tab, index) => (
            <button
              key={tab.id}
              className={activeTab === tab.id ? "active" : ""}
              type="button"
              onClick={() => handleTabChange(tab)}
              disabled={!isReady || isGenerating}
            >
              <span>0{index + 1}</span>
              {tab.label}
            </button>
          ))}
        </nav>}
      </header>
      <main className="canvas-wrap">
        {!hasEntered && <section className="landing-hero">
          <span className="eyebrow">A local, living portfolio</span>
          <h1>Ideas in<br /><em>motion.</em></h1>
          <p>Luke Cheng builds resilient systems, curious tools, and new ways to make complex work feel clear.</p>
          <button type="button" className="landing-enter" onClick={enterPortfolio}>Click the title to enter <span>↓</span></button>
          <div className="landing-index"><span>01 / 01</span><span>New York · 2026</span><span>Built with Chrome’s local AI</span></div>
        </section>}
        {hasEntered && availability !== "available" && !isReady && (
          <section className="ai-gate" aria-live="polite">
            <span className="eyebrow">Local inference layer</span>
            <h2>
              {availability === "unavailable"
                ? "This portfolio needs Chrome’s built-in AI."
                : availability === "downloading"
                  ? "The model is arriving locally."
                  : "A browser-native portfolio, still warming up."}
            </h2>
            <p>
              {availability === "unavailable"
                ? "Open this site in a supported desktop version of Chrome with Prompt API access. The editorial preview remains available below."
                : "The first visit downloads the model to your device. Nothing in this portfolio is sent to a remote AI service."}
            </p>
            {availability === "downloading" && (
              <div className="progress-track">
                <span style={{ width: `${Math.max(progress * 100, 4)}%` }} />
              </div>
            )}
            {availability !== "unavailable" &&
              availability !== "downloading" && (
                <button
                  className="primary-button"
                  type="button"
                  onClick={activateModel}
                >
                  Enable local AI <span>↗</span>
                </button>
              )}
            {error && <p className="error-message">{error}</p>}
          </section>
        )}
        {hasEntered && <section
          className={`generated-canvas ${isGenerating ? "is-generating" : ""}`}
          aria-live="polite"
          dangerouslySetInnerHTML={{ __html: sanitizeCanvas(canvas) }}
        />}
        {hasEntered && isGenerating && (
          <div className="generation-note">
            <span className="pulse" /> Composing a new view{" "}
            <button type="button" onClick={() => abortRef.current?.abort()}>
              Stop
            </button>
          </div>
        )}
        {hasEntered && error && isReady && (
          <div className="inline-error">
            {error}{" "}
            <button type="button" onClick={() => setError("")}>
              Dismiss
            </button>
          </div>
        )}
      </main>
      <footer className="site-footer">
        <p>
          <span className="footer-signal" /> Content and layout are generated
          locally by your browser’s AI. Changing views may generate new content.
        </p>
        <div className="footer-links">
          <a
            href="https://github.com/Luke-Cheng"
            target="_blank"
            rel="noreferrer"
          >
            GitHub ↗
          </a>
          <a
            href="https://www.linkedin.com/in/luke-cheng/"
            target="_blank"
            rel="noreferrer"
          >
            LinkedIn ↗
          </a>
          <a href="/portfolio.md">View source ↗</a>
        </div>
      </footer>
    </div>
  );
}

export default App;

@import url("https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;1,500&display=swap");
:root {
  --ink: #171917;
  --muted: #6d7369;
  --paper: #f1f0e9;
  --line: #c8c9bd;
  --acid: #d9ff4f;
  --coral: #ff6b4a;
  --mono: "DM Mono", monospace;
  --sans: "Manrope", sans-serif;
  --serif: "Playfair Display", serif;
}
* {
  box-sizing: border-box;
}
body {
  color: var(--ink);
  background: var(--paper);
  font: 15px/1.6 var(--sans);
}
button,
input {
  font: inherit;
}
button {
  color: inherit;
  cursor: pointer;
}
.site-shell {
  max-width: 1440px;
  min-height: 100svh;
  margin: auto;
  padding: 0 4vw 94px;
}
.site-header {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 34px 48px;
  padding: 30px 0 0;
  border-bottom: 1px solid var(--ink);
}
.site-header.is-landing {
  min-height: 112px;
  border-bottom-color: var(--line);
}
.identity {
  display: flex;
  align-items: flex-start;
  gap: 18px;
  position: relative;
  border: 0;
  background: transparent;
  padding: 0;
  text-align: left;
}
.site-header.is-landing .identity {
  width: 100%;
  min-height: 82px;
}
.identity-action {
  margin-left: auto;
  align-self: center;
  color: var(--coral);
  font: 11px var(--mono);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  transition: transform 0.3s ease;
}
.identity-action b {
  display: inline-block;
  margin-left: 9px;
  font-size: 16px;
  font-weight: 400;
}
.identity:hover .identity-action { transform: translateX(6px); }
}
.identity-mark,
.eyebrow,
.model-status,
.tab-nav span {
  font: 11px var(--mono);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.identity-mark {
  background: var(--ink);
  color: var(--acid);
  padding: 7px 8px;
}
.identity strong {
  display: block;
  font-size: 16px;
  letter-spacing: -0.03em;
}
.identity div span {
  display: block;
  color: var(--muted);
  font-size: 12px;
}
.model-status {
  align-self: start;
  color: var(--muted);
}
.status-dot,
.footer-signal,
.pulse {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 8px;
  border-radius: 50%;
  background: var(--coral);
}
.status-dot.ready,
.footer-signal {
  background: #60a436;
}
.question-bar {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  max-width: 780px;
  border-bottom: 1px solid var(--ink);
}
.prompt-symbol {
  color: var(--coral);
  font: 24px var(--serif);
  padding-right: 10px;
}
.question-bar input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  padding: 15px 0;
  color: var(--ink);
}
.question-bar input::placeholder {
  color: var(--muted);
}
.question-bar button,
.primary-button {
  border: 0;
  background: var(--ink);
  color: var(--acid);
  padding: 9px 13px;
  font: 11px var(--mono);
  text-transform: uppercase;
}
.question-bar button:disabled,
.tab-nav button:disabled {
  cursor: wait;
  opacity: 0.45;
}
.tab-nav {
  grid-column: 1 / -1;
  display: flex;
  align-items: end;
  gap: 26px;
  overflow-x: auto;
}
.tab-nav button {
  position: relative;
  border: 0;
  background: transparent;
  padding: 0 0 14px;
  text-align: left;
  white-space: nowrap;
}
.tab-nav button span {
  margin-right: 10px;
  color: var(--coral);
}
.tab-nav button.active::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 3px;
  background: var(--coral);
  content: "";
}
.canvas-wrap {
  position: relative;
  padding: 74px 0 80px;
}
.ai-gate {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 40px;
  margin-bottom: 76px;
  padding: 22px 0;
  border-top: 1px solid var(--coral);
  border-bottom: 1px solid var(--line);
}
.ai-gate .eyebrow {
  grid-column: 1 / -1;
  color: var(--coral);
}
.ai-gate h2 {
  max-width: 550px;
  margin: 0;
  font-size: clamp(24px, 3vw, 42px);
  line-height: 1.06;
  letter-spacing: -0.05em;
}
.ai-gate p {
  max-width: 480px;
  margin: 0;
  color: var(--muted);
}
.primary-button {
  align-self: start;
  justify-self: start;
  margin-top: 12px;
}
.progress-track {
  grid-column: 2;
  height: 5px;
  margin-top: 14px;
  background: var(--line);
}
.progress-track span {
  display: block;
  height: 100%;
  background: var(--coral);
  transition: width 0.3s ease;
}
.error-message {
  grid-column: 1 / -1;
  color: var(--coral) !important;
}
.generated-canvas {
  min-height: 520px;
  transition: opacity 0.25s ease;
}
.generated-canvas.is-generating {
  opacity: 0.62;
}
.canvas-intro {
  max-width: 900px;
}
.eyebrow {
  color: var(--muted);
}
.canvas-intro h1 {
  max-width: 850px;
  margin: 22px 0 26px;
  font-size: clamp(54px, 8vw, 126px);
  font-weight: 500;
  line-height: 0.91;
  letter-spacing: -0.08em;
}
.canvas-intro h1 em {
  color: var(--coral);
  font-family: var(--serif);
  font-weight: 500;
  letter-spacing: -0.05em;
}
.lead {
  max-width: 600px;
  color: var(--muted);
  font-size: 19px;
}
.canvas-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 260px;
  gap: 12vw;
  max-width: 980px;
  margin: 130px 0 0 auto;
}
.feature-block {
  border-top: 1px solid var(--ink);
  padding-top: 14px;
}
.feature-block h2 {
  max-width: 500px;
  margin: 28px 0 20px;
  font-size: clamp(30px, 4vw, 58px);
  line-height: 0.98;
  letter-spacing: -0.06em;
}
.feature-block p:not(.eyebrow) {
  max-width: 550px;
  color: var(--muted);
}
.margin-note {
  align-self: end;
  border-top: 1px solid var(--coral);
  padding-top: 11px;
  color: var(--muted);
  font: 12px/1.45 var(--mono);
}
.margin-note span {
  display: block;
  margin-bottom: 20px;
  color: var(--coral);
}
.signal-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 120px;
  border-top: 1px solid var(--ink);
  border-bottom: 1px solid var(--ink);
  padding: 22px 0;
}
.signal-row div {
  display: flex;
  flex-direction: column;
}
.signal-row strong {
  font-size: clamp(32px, 4vw, 58px);
  font-weight: 500;
  line-height: 1;
  letter-spacing: -0.06em;
}
.signal-row span {
  margin-top: 9px;
  color: var(--muted);
  font: 11px var(--mono);
  text-transform: uppercase;
}
.generation-note,
.inline-error {
  position: fixed;
  right: 4vw;
  bottom: 78px;
  z-index: 2;
  padding: 9px 12px;
  background: var(--ink);
  color: var(--paper);
  font: 11px var(--mono);
}
.generation-note button,
.inline-error button {
  margin-left: 12px;
  border: 0;
  border-bottom: 1px solid currentColor;
  background: transparent;
  color: var(--acid);
  font: inherit;
}
.pulse {
  animation: pulse 1s infinite;
}
.site-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
  position: fixed;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 3;
  padding: 13px 4vw;
  border-top: 1px solid var(--ink);
  background: var(--paper);
  font-size: 11px;
}
.site-footer p {
  margin: 0;
  color: var(--muted);
}
.footer-links {
  display: flex;
  gap: 18px;
  white-space: nowrap;
}
.site-footer a {
  color: var(--ink);
  text-decoration: none;
}
.site-footer a:hover {
  color: var(--coral);
}
@keyframes pulse {
  50% {
    opacity: 0.25;
  }
}
@media (max-width: 700px) {
  .site-shell {
    padding: 0 20px 118px;
  }
  .site-header {
    gap: 24px 12px;
  }
  .model-status {
    grid-column: 1 / -1;
    grid-row: 2;
  }
  .question-bar {
    grid-row: 3;
  }
  .tab-nav {
    grid-row: 4;
    gap: 20px;
  }
  .canvas-wrap {
    padding-top: 48px;
  }
  .ai-gate {
    display: block;
    margin-bottom: 50px;
  }
  .ai-gate h2 {
    margin: 12px 0;
  }
  .ai-gate p {
    margin-bottom: 18px;
  }
  .progress-track {
    margin-bottom: 16px;
  }
  .canvas-intro h1 {
    font-size: clamp(48px, 15vw, 90px);
  }
  .canvas-grid {
    display: block;
    margin-top: 80px;
  }
  .margin-note {
    margin-top: 35px;
  }
  .signal-row {
    margin-top: 75px;
  }
  .signal-row strong {
    font-size: 35px;
  }
  .site-footer {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
    padding: 12px 20px;
  }
  .generation-note,
  .inline-error {
    right: 20px;
    bottom: 103px;
  }
}

