@import url("https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;1,500&display=swap");
:root {
  --ink: #171917;
  --muted: #6d7369;
  --paper: #f1f0e9;
  --line: #c8c9bd;
  --acid: #d9ff4f;
  --coral: #ff6b4a;
  --mono: "DM Mono", monospace;
  --sans: "Manrope", sans-serif;
  --serif: "Playfair Display", serif;
}
* {
  box-sizing: border-box;
}
body {
  color: var(--ink);
  background: var(--paper);
  font: 15px/1.6 var(--sans);
}
button,
input {
  font: inherit;
}
button {
  color: inherit;
  cursor: pointer;
}
.site-shell {
  max-width: 1440px;
  min-height: 100svh;
  margin: auto;
  padding: 0 4vw 94px;
}
.site-header {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 34px 48px;
  padding: 30px 0 0;
  border-bottom: 1px solid var(--ink);
}
.site-header.is-landing {
  min-height: 112px;
  border-bottom-color: var(--line);
}
.identity {
  display: flex;
  align-items: flex-start;
  gap: 18px;
  position: relative;
  border: 0;
  background: transparent;
  padding: 0;
  text-align: left;
}
.site-header.is-landing .identity {
  width: 100%;
  min-height: 82px;
}
.identity-action {
  margin-left: auto;
  align-self: center;
  color: var(--coral);
  font: 11px var(--mono);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  transition: transform 0.3s ease;
}
.identity-action b {
  display: inline-block;
  margin-left: 9px;
  font-size: 16px;
  font-weight: 400;
}
.identity:hover .identity-action { transform: translateX(6px); }
}
.identity-mark,
.eyebrow,
.model-status,
.tab-nav span {
  font: 11px var(--mono);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.identity-mark {
  background: var(--ink);
  color: var(--acid);
  padding: 7px 8px;
}
.identity strong {
  display: block;
  font-size: 16px;
  letter-spacing: -0.03em;
}
.identity div span {
  display: block;
  color: var(--muted);
  font-size: 12px;
}
.model-status {
  align-self: start;
  color: var(--muted);
}
.status-dot,
.footer-signal,
.pulse {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 8px;
  border-radius: 50%;
  background: var(--coral);
}
.status-dot.ready,
.footer-signal {
  background: #60a436;
}
.question-bar {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  max-width: 780px;
  border-bottom: 1px solid var(--ink);
}
.prompt-symbol {
  color: var(--coral);
  font: 24px var(--serif);
  padding-right: 10px;
}
.question-bar input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  padding: 15px 0;
  color: var(--ink);
}
.question-bar input::placeholder {
  color: var(--muted);
}
.question-bar button,
.primary-button {
  border: 0;
  background: var(--ink);
  color: var(--acid);
  padding: 9px 13px;
  font: 11px var(--mono);
  text-transform: uppercase;
}
.question-bar button:disabled,
.tab-nav button:disabled {
  cursor: wait;
  opacity: 0.45;
}
.tab-nav {
  grid-column: 1 / -1;
  display: flex;
  align-items: end;
  gap: 26px;
  overflow-x: auto;
}
.tab-nav button {
  position: relative;
  border: 0;
  background: transparent;
  padding: 0 0 14px;
  text-align: left;
  white-space: nowrap;
}
.tab-nav button span {
  margin-right: 10px;
  color: var(--coral);
}
.tab-nav button.active::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 3px;
  background: var(--coral);
  content: "";
}
.canvas-wrap {
  position: relative;
  padding: 74px 0 80px;
}
.ai-gate {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 40px;
  margin-bottom: 76px;
  padding: 22px 0;
  border-top: 1px solid var(--coral);
  border-bottom: 1px solid var(--line);
}
.ai-gate .eyebrow {
  grid-column: 1 / -1;
  color: var(--coral);
}
.ai-gate h2 {
  max-width: 550px;
  margin: 0;
  font-size: clamp(24px, 3vw, 42px);
  line-height: 1.06;
  letter-spacing: -0.05em;
}
.ai-gate p {
  max-width: 480px;
  margin: 0;
  color: var(--muted);
}
.primary-button {
  align-self: start;
  justify-self: start;
  margin-top: 12px;
}
.progress-track {
  grid-column: 2;
  height: 5px;
  margin-top: 14px;
  background: var(--line);
}
.progress-track span {
  display: block;
  height: 100%;
  background: var(--coral);
  transition: width 0.3s ease;
}
.error-message {
  grid-column: 1 / -1;
  color: var(--coral) !important;
}
.generated-canvas {
  min-height: 520px;
  transition: opacity 0.25s ease;
}
.generated-canvas.is-generating {
  opacity: 0.62;
}
.canvas-intro {
  max-width: 900px;
}
.eyebrow {
  color: var(--muted);
}
.canvas-intro h1 {
  max-width: 850px;
  margin: 22px 0 26px;
  font-size: clamp(54px, 8vw, 126px);
  font-weight: 500;
  line-height: 0.91;
  letter-spacing: -0.08em;
}
.canvas-intro h1 em {
  color: var(--coral);
  font-family: var(--serif);
  font-weight: 500;
  letter-spacing: -0.05em;
}
.lead {
  max-width: 600px;
  color: var(--muted);
  font-size: 19px;
}
.canvas-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 260px;
  gap: 12vw;
  max-width: 980px;
  margin: 130px 0 0 auto;
}
.feature-block {
  border-top: 1px solid var(--ink);
  padding-top: 14px;
}
.feature-block h2 {
  max-width: 500px;
  margin: 28px 0 20px;
  font-size: clamp(30px, 4vw, 58px);
  line-height: 0.98;
  letter-spacing: -0.06em;
}
.feature-block p:not(.eyebrow) {
  max-width: 550px;
  color: var(--muted);
}
.margin-note {
  align-self: end;
  border-top: 1px solid var(--coral);
  padding-top: 11px;
  color: var(--muted);
  font: 12px/1.45 var(--mono);
}
.margin-note span {
  display: block;
  margin-bottom: 20px;
  color: var(--coral);
}
.signal-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 120px;
  border-top: 1px solid var(--ink);
  border-bottom: 1px solid var(--ink);
  padding: 22px 0;
}
.signal-row div {
  display: flex;
  flex-direction: column;
}
.signal-row strong {
  font-size: clamp(32px, 4vw, 58px);
  font-weight: 500;
  line-height: 1;
  letter-spacing: -0.06em;
}
.signal-row span {
  margin-top: 9px;
  color: var(--muted);
  font: 11px var(--mono);
  text-transform: uppercase;
}
.generation-note,
.inline-error {
  position: fixed;
  right: 4vw;
  bottom: 78px;
  z-index: 2;
  padding: 9px 12px;
  background: var(--ink);
  color: var(--paper);
  font: 11px var(--mono);
}
.generation-note button,
.inline-error button {
  margin-left: 12px;
  border: 0;
  border-bottom: 1px solid currentColor;
  background: transparent;
  color: var(--acid);
  font: inherit;
}
.pulse {
  animation: pulse 1s infinite;
}
.site-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
  position: fixed;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 3;
  padding: 13px 4vw;
  border-top: 1px solid var(--ink);
  background: var(--paper);
  font-size: 11px;
}
.site-footer p {
  margin: 0;
  color: var(--muted);
}
.footer-links {
  display: flex;
  gap: 18px;
  white-space: nowrap;
}
.site-footer a {
  color: var(--ink);
  text-decoration: none;
}
.site-footer a:hover {
  color: var(--coral);
}
@keyframes pulse {
  50% {
    opacity: 0.25;
  }
}
@media (max-width: 700px) {
  .site-shell {
    padding: 0 20px 118px;
  }
  .site-header {
    gap: 24px 12px;
  }
  .model-status {
    grid-column: 1 / -1;
    grid-row: 2;
  }
  .question-bar {
    grid-row: 3;
  }
  .tab-nav {
    grid-row: 4;
    gap: 20px;
  }
  .canvas-wrap {
    padding-top: 48px;
  }
  .ai-gate {
    display: block;
    margin-bottom: 50px;
  }
  .ai-gate h2 {
    margin: 12px 0;
  }
  .ai-gate p {
    margin-bottom: 18px;
  }
  .progress-track {
    margin-bottom: 16px;
  }
  .canvas-intro h1 {
    font-size: clamp(48px, 15vw, 90px);
  }
  .canvas-grid {
    display: block;
    margin-top: 80px;
  }
  .margin-note {
    margin-top: 35px;
  }
  .signal-row {
    margin-top: 75px;
  }
  .signal-row strong {
    font-size: 35px;
  }
  .site-footer {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
    padding: 12px 20px;
  }
  .generation-note,
  .inline-error {
    right: 20px;
    bottom: 103px;
  }
}

