  color: var(--muted);
  font: 11px/1.5 var(--sans);
  opacity: 0;
  pointer-events: none;
  transform: translateY(5px);
  transition: opacity 0.15s ease, transform 0.15s ease;
}
.ai-info-popover::after {
  position: absolute;
  right: 28px;
  bottom: -7px;
  width: 12px;
  height: 12px;
  border-right: 1px solid var(--ink);
  border-bottom: 1px solid var(--ink);
  background: var(--paper);
  content: "";
  transform: rotate(45deg);
}
.ai-info:hover .ai-info-popover,
.ai-info:focus-within .ai-info-popover {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}
.ai-info-popover strong {
  display: block;
  margin-bottom: 9px;
  color: var(--ink);
  font: 11px var(--mono);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.ai-info-popover p {
  margin: 0 0 9px;
}
.ai-info-popover p .status-dot {
  width: 6px;
  height: 6px;
  margin-right: 7px;
}
.ai-info-popover small {
  display: block;
  color: var(--ink);
  font-size: 10px;
}
.submit-button {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 0;
  background: var(--ink);
  color: var(--acid);
  font: 20px/1 var(--sans);
}
.submit-button:disabled {
  cursor: wait;
  opacity: 0.45;
}
.question-bar button:disabled,
.tab-nav button:disabled {
  cursor: wait;
  opacity: 0.45;
}
.tab-nav {
  display: flex;
  align-items: end;
  gap: 26px;
  overflow-x: auto;
}
.tab-nav button {
  position: relative;
  border: 0;
  background: transparent;
  padding: 0 0 14px;
  text-align: left;
  white-space: nowrap;
}
.tab-nav button span {
  margin-right: 10px;
  color: var(--coral);
}
.tab-nav button.active::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 3px;
  background: var(--coral);
