.landing-canvas p:last-child {
  color: var(--muted);
  font: 11px var(--mono);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.generated-canvas {
  min-height: 520px;
  transition: opacity 0.25s ease;
}
.generated-canvas.is-generating {
  opacity: 0.62;
}
.canvas-intro {
  max-width: 900px;
}
.eyebrow {
  color: var(--muted);
}
.canvas-intro h1 {
  max-width: 850px;
  margin: 22px 0 26px;
  font-size: clamp(54px, 8vw, 126px);
  font-weight: 500;
  line-height: 0.91;
  letter-spacing: -0.08em;
}
.canvas-intro h1 em {
  color: var(--coral);
  font-family: var(--serif);
  font-weight: 500;
  letter-spacing: -0.05em;
}
.lead {
  max-width: 600px;
  color: var(--muted);
  font-size: 19px;
}
.canvas-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 260px;
  gap: 12vw;
  max-width: 980px;
  margin: 130px 0 0 auto;
}
.feature-block {
  border-top: 1px solid var(--ink);
  padding-top: 14px;
}
.feature-block h2 {
  max-width: 500px;
  margin: 28px 0 20px;
  font-size: clamp(30px, 4vw, 58px);
  line-height: 0.98;
  letter-spacing: -0.06em;
}
.feature-block p:not(.eyebrow) {
  max-width: 550px;
  color: var(--muted);
}
.margin-note {
  align-self: end;
  border-top: 1px solid var(--coral);
  padding-top: 11px;
  color: var(--muted);
  font: 12px/1.45 var(--mono);
}
.margin-note span {
  display: block;
  margin-bottom: 20px;
  color: var(--coral);
}
.signal-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 120px;
  border-top: 1px solid var(--ink);
  border-bottom: 1px solid var(--ink);
  padding: 22px 0;
}
.signal-row div {
  display: flex;
  flex-direction: column;
}
.signal-row strong {
  font-size: clamp(32px, 4vw, 58px);
  font-weight: 500;
  line-height: 1;
  letter-spacing: -0.06em;
}
.signal-row span {
  margin-top: 9px;
  color: var(--muted);
  font: 11px var(--mono);
  text-transform: uppercase;
}
.generation-note,
.inline-error {
  position: fixed;
  right: 4vw;
  bottom: 78px;
  z-index: 2;
  padding: 9px 12px;
  background: var(--ink);
  color: var(--paper);
  font: 11px var(--mono);
}
.generation-note button,
.inline-error button {
  margin-left: 12px;
  border: 0;
  border-bottom: 1px solid currentColor;
  background: transparent;
  color: var(--acid);
  font: inherit;
}
.pulse {
  animation: pulse 1s infinite;
}
.site-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
  position: fixed;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 3;
  padding: 13px 4vw;
  border-top: 1px solid var(--ink);
  background: var(--paper);
  font-size: 11px;
}
.site-footer p {
  margin: 0;
  color: var(--muted);
}
.footer-links {
  display: flex;
  gap: 18px;
  white-space: nowrap;
}
.site-footer a {
  color: var(--ink);
  text-decoration: none;
}
.site-footer a:hover {
  color: var(--coral);
}
@keyframes pulse {
  50% {
    opacity: 0.25;
  }
  .ai-info-trigger span:last-child {
    display: none;
  }
}
@media (max-width: 700px) {
  .site-shell {
    padding: 0 20px 118px;
  }
  .site-header {
    padding-top: 22px;
  }
  .header-top { align-items: flex-start; flex-direction: column; gap: 24px; }
  .header-bottom { align-items: stretch; flex-direction: column-reverse; gap: 12px; padding-top: 28px; }
  .model-status {
    align-self: flex-start;
  }
  .tab-nav {
    gap: 20px;
  }
  .canvas-wrap {
    padding-top: 62px;
  }
  .ai-gate {
    align-items: flex-start;
    flex-wrap: wrap;
  }
  .progress-track {
    flex-basis: 100%;
  }
  .primary-button { margin-left: 0; }
  .landing-canvas { min-height: 62vh; padding-top: 18vh; }
  .canvas-intro h1 {
    font-size: clamp(48px, 15vw, 90px);
  }
  .canvas-grid {
    display: block;
    margin-top: 80px;
  }
  .margin-note {
    margin-top: 35px;
  }
  .signal-row {
    margin-top: 75px;
  }
  .signal-row strong {
    font-size: 35px;
  }
  .site-footer {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
    padding: 12px 20px;
  }
  .generation-note,
  .inline-error {
    right: 20px;
    bottom: 103px;
  }
}

