edits.text:
@import url("https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;1,500&display=swap");
:root {
  color-scheme: light dark;
  --ink: #171917;
  --muted: #6d7369;
  --paper: #f1f0e9;
  --line: #c8c9bd;
  --acid: #d9ff4f;
  --coral: #ff6b4a;
  --mono: "DM Mono", monospace;
  --sans: "Manrope", sans-serif;
  --serif: "Playfair Display", serif;
}
@media (prefers-color-scheme: dark) {
  :root {
    --ink: #f0f0e8;
    --muted: #a5aa9e;
    --paper: #171917;
    --line: #41453d;
    --acid: #d9ff4f;
    --coral: #ff8064;
  }
}
* {
  box-sizing: border-box;
}
body {
  color: var(--ink);
  background: var(--paper);
  font: 15px/1.6 var(--sans);
}
button,
input {
  font: inherit;
}
button {
  color: inherit;
  cursor: pointer;
}
.site-shell {
  max-width: 1440px;
  min-height: 100svh;
  margin: auto;
  padding: 0 4vw 94px;
}
.site-header {
  padding: 32px 0 0;
  border-bottom: 1px solid var(--ink);
}
.header-top,
.header-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.header-top {
  min-height: 54px;
}
.header-bottom {
  gap: 30px;
  padding: 30px 0 18px;
}
.identity {
  flex: 0 0 auto;
}
.eyebrow,
.model-status,
.tab-nav span {
  font: 11px var(--mono);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.identity strong {
  display: block;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.05em;
}
.model-status {
  flex: 0 0 auto;
  color: var(--muted);
  font-size: 10px;
}
.status-dot,
.footer-signal,
.pulse {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 8px;
  border-radius: 50%;
  background: var(--coral);
}
.status-dot.ready,
.footer-signal {
  background: #60a436;
}
.question-bar {
  display: flex;
  align-items: center;
  flex: 1;
  max-width: none;
}
.prompt-symbol {
  color: var(--coral);
  font: 24px var(--serif);
  padding-right: 10px;
}
.question-bar input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  padding: 15px 0;
  color: var(--ink);
}
.question-bar input::placeholder {
  color: var(--muted);
}
.primary-button {
  border: 0;
  background: var(--ink);
  color: var(--acid);
  padding: 9px 13px;
  font: 11px var(--mono);
  text-transform: uppercase;
}
.ai-info {
  position: relative;
  flex: 0 0 auto;
}
.ai-info-trigger {
  display: flex;
  align-items: center;
  border: 0;
  background: transparent;
  color: var(--muted);
  padding: 8px 12px;
  font: 10px var(--mono);
  white-space: nowrap;
}
.ai-info-trigger .status-dot {
  width: 6px;
  height: 6px;
  margin-right: 7px;
}
.ai-info-trigger:hover,
.ai-info-trigger:focus-visible {
  color: var(--ink);
  outline: 1px solid var(--line);
  outline-offset: -1px;
}
.ai-info-popover {
  position: absolute;
  right: 0;
  top: calc(100% + 14px);
  z-index: 5;
  width: min(330px, calc(100vw - 40px));
  padding: 16px;
  border: 1px solid var(--ink);
  background: var(--paper);
  box-shadow: 6px 6px 0 var(--coral);
  color: var(--muted);
  font: 11px/1.5 var(--sans);
  opacity: 0;
  pointer-events: none;
  transform: translateY(5px);
  transition: opacity 0.15s ease, transform 0.15s ease;
}
.ai-info-popover::after {
  position: absolute;
  right: 28px;
  top: -7px;
  width: 12px;
  height: 12px;
  border-top: 1px solid var(--ink);
  border-left: 1px solid var(--ink);
  background: var(--paper);
  content: "";
  transform: rotate(45deg);
}
.ai-info:hover .ai-info-popover,
.ai-info:focus-within .ai-info-popover {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}
.ai-info-popover strong {
  display: block;
  margin-bottom: 9px;
  color: var(--ink);
  font: 11px var(--mono);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.ai-info-popover p {
  margin: 0 0 9px;
}
.ai-info-popover p .status-dot {
  width: 6px;
  height: 6px;
  margin-right: 7px;
}
.ai-info-popover small {
  display: block;
  color: var(--ink);
  font-size: 10px;
}
.submit-button {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 0;
  background: var(--ink);
  color: var(--acid);
  font: 20px/1 var(--sans);
}
.submit-button:disabled {
  cursor: wait;
  opacity: 0.45;
}
.question-bar button:disabled,
.tab-nav button:disabled {
  cursor: wait;
  opacity: 0.45;
}
.tab-nav {
  display: flex;
  align-items: end;
  gap: 26px;
  overflow-x: auto;
}
.tab-nav button {
  position: relative;
  border: 0;
  background: transparent;
  padding: 0 0 14px;
  text-align: left;
  white-space: nowrap;
}
.tab-nav button span {
  margin-right: 10px;
  color: var(--coral);
}
.tab-nav button.active::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 3px;
  background: var(--coral);
  content: "";
}
.canvas-wrap {
  position: relative;
  padding: 112px 0 80px;
}
.ai-gate {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 25px;
  padding: 10px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  color: var(--muted);
  font-size: 12px;
}
.ai-gate h2 {
  max-width: none;
  margin: 0;
  font: inherit;
}
.primary-button {
  margin-left: auto;
}
.progress-track {
  flex: 0 1 180px;
  height: 5px;
  background: var(--line);
}
.progress-track span {
  display: block;
  height: 100%;
  background: var(--coral);
  transition: width 0.3s ease;
}
.error-message {
  color: var(--coral) !important;
}
.landing-canvas {
  min-height: 54vh;
  padding-top: 15vh;
  text-align: center;
}
.landing-canvas h1 {
  margin: 20px 0 10px;
  font-size: clamp(44px, 8vw, 108px);
  font-weight: 500;
  line-height: 0.95;
  letter-spacing: -0.08em;
}
.landing-canvas p:last-child {
  color: var(--muted);
  font: 11px var(--mono);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.generated-canvas {
  min-height: 520px;
  transition: opacity 0.25s ease;
}
.generated-canvas.is-generating {
  opacity: 0.62;
}
.canvas-intro {
  max-width: 900px;
}
.eyebrow {
  color: var(--muted);
}
.canvas-intro h1 {
  max-width: 850px;
  margin: 22px 0 26px;
  font-size: clamp(54px, 8vw, 126px);
  font-weight: 500;
  line-height: 0.91;
  letter-spacing: -0.08em;
}
.canvas-intro h1 em {
  color: var(--coral);
  font-family: var(--serif);
  font-weight: 500;
  letter-spacing: -0.05em;
}
.lead {
  max-width: 600px;
  color: var(--muted);
  font-size: 19px;
}
.canvas-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 260px;
  gap: 12vw;
  max-width: 980px;
  margin: 130px 0 0 auto;
}
.feature-block {
  border-top: 1px solid var(--ink);
  padding-top: 14px;
}
.feature-block h2 {
  max-width: 500px;
  margin: 28px 0 20px;
  font-size: clamp(30px, 4vw, 58px);
  line-height: 0.98;
  letter-spacing: -0.06em;
}
.feature-block p:not(.eyebrow) {
  max-width: 550px;
