@import url("https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;1,500&display=swap");
:root {
  color-scheme: light dark;
  --ink: #171917;
  --muted: #6d7369;
  --paper: #f1f0e9;
  --line: #c8c9bd;
  --acid: #d9ff4f;
  --coral: #ff6b4a;
  --mono: "DM Mono", monospace;
  --sans: "Manrope", sans-serif;
  --serif: "Playfair Display", serif;
}
@media (prefers-color-scheme: dark) {
  :root {
    --ink: #f0f0e8;
    --muted: #a5aa9e;
    --paper: #171917;
    --line: #41453d;
    --acid: #d9ff4f;
    --coral: #ff8064;
  }
}
* {
  box-sizing: border-box;
}
body {
  color: var(--ink);
  background: var(--paper);
  font: 15px/1.6 var(--sans);
}
button,
input {
  font: inherit;
}
button {
  color: inherit;
  cursor: pointer;
}
.site-shell {
  max-width: 1440px;
  min-height: 100svh;
  margin: auto;
  padding: 0 4vw 94px;
}
.site-header {
  padding: 32px 0 0;
  border-bottom: 1px solid var(--ink);
}
.header-top,
.header-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.header-top {
  min-height: 54px;
}
.header-bottom {
  gap: 30px;
  padding: 30px 0 18px;
}
.identity {
  flex: 0 0 auto;
}
.eyebrow,
.model-status,
.tab-nav span {
  font: 11px var(--mono);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.identity strong {
  display: block;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.05em;
}
.model-status {
  flex: 0 0 auto;
  color: var(--muted);
  font-size: 10px;
}
.status-dot,
.footer-signal,
.pulse {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 8px;
  border-radius: 50%;
  background: var(--coral);
}
.status-dot.ready,
.footer-signal {
  background: #60a436;
}
.question-bar {
  display: flex;
  align-items: center;
  flex: 1;
  max-width: none;
}
.prompt-symbol {
  color: var(--coral);
  font: 24px var(--serif);
  padding-right: 10px;
}
.question-bar input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  padding: 15px 0;
  color: var(--ink);
}
.question-bar input::placeholder {
  color: var(--muted);
}
.primary-button {
  border: 0;
  background: var(--ink);
  color: var(--acid);
  padding: 9px 13px;
  font: 11px var(--mono);
  text-transform: uppercase;
}
.submit-button {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 0;
  background: var(--ink);
  color: var(--acid);
  font: 20px/1 var(--sans);
}
.submit-button:disabled {
  cursor: wait;
  opacity: 0.45;
}
.question-bar button:disabled,
.tab-nav button:disabled {
  cursor: wait;
  opacity: 0.45;
}
.tab-nav {
  display: flex;
  align-items: end;
  gap: 26px;
  overflow-x: auto;
}
.tab-nav button {
  position: relative;
  border: 0;
  background: transparent;
  padding: 0 0 14px;
  text-align: left;
  white-space: nowrap;
}
.tab-nav button span {
  margin-right: 10px;
  color: var(--coral);
}
.tab-nav button.active::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 3px;
  background: var(--coral);
  content: "";
}
.canvas-wrap {
  position: relative;
  padding: 112px 0 80px;
}
.ai-gate {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 25px;
  padding: 10px 0;
